module legacy_binary_names;
pub struct bytes { data:list<i64>; }
fn utf8_bytes(value:str) -> str { return value; }
fn decode_utf8(value:str) -> str { return value; }
fn encode_base64(value:str) -> str { return value; }
fn decode_base64(value:str) -> str { return value; }
fn identity<T:wire>(value:T) -> T { return unwrap(decode_json<T>(encode_json(value))); }
fn transform(f:fn(bytes)->bytes,value:bytes) -> bytes { return f(value); }
fn main() -> unit !{io} {
  let original:bytes = bytes([0,255,128]);
  let captured:fn(bytes)->bytes = fn(value:bytes)->bytes { return bytes(original.data+value.data); };
  print(identity(transform(captured,bytes([1]))));
  print(decode_base64(encode_base64(decode_utf8(utf8_bytes("Я🧠")))));
}
test fn preserved_names() -> unit {
  assert(identity(bytes([0,255,128])).data==[0,255,128]);
  assert(decode_base64(encode_base64(decode_utf8(utf8_bytes("text"))))=="text");
}
